  3→import { useState, useEffect, useRef } from 'react';
  4→
  5→interface SearchBarProps {
  6→  isOpen: boolean;
  7→  onClose: () => void;
  8→}
  9→
 10→export function SearchBar({ isOpen, onClose }: SearchBarProps) {
 11→  const [searchQuery, setSearchQuery] = useState('');
 12→  const inputRef = useRef<HTMLInputElement>(null);
 13→
 14→  // Focus input when search bar opens
 15→  useEffect(() => {
 16→    if (isOpen && inputRef.current) {
 17→      inputRef.current.focus();
 18→    }
 19→  }, [isOpen]);
 20→
 21→  // Handle escape key to close
 22→  useEffect(() => {
 23→    const handleEscape = (e: KeyboardEvent) => {
 24→      if (e.key === 'Escape' && isOpen) {
 25→        onClose();
 26→      }
 27→    };
 28→
 29→    document.addEventListener('keydown', handleEscape);
 30→    return () => document.removeEventListener('keydown', handleEscape);
 31→  }, [isOpen, onClose]);
 32→
 33→  if (!isOpen) return null;
 34→
 35→  return (
 36→    <div
 37→      className="fixed inset-0 z-50 flex items-start justify-center pt-32"
 38→      onClick={onClose}
 39→      style={{
 40→        backgroundColor: 'rgba(255, 255, 255, 0.92)',
 41→        backdropFilter: 'blur(8px)',
 42→        animation: 'fadeIn 300ms ease-out'
 43→      }}
 44→    >
 45→      <div
 46→        className="w-full max-w-2xl px-6"
 47→        onClick={(e) => e.stopPropagation()}
 48→        style={{
 49→          animation: 'slideDown 400ms cubic-bezier(0.16, 1, 0.3, 1)'
 50→        }}
 51→      >
 52→        {/* Search Input */}
 53→        <div
 54→          className="relative"
 55→          style={{
 56→            borderBottom: '2px solid var(--text-muted)',
 57→            paddingBottom: '12px'
 58→          }}
 59→        >
 60→          <input
 61→            ref={inputRef}
 62→            type="text"
 63→            value={searchQuery}
 64→            onChange={(e) => setSearchQuery(e.target.value)}
 65→            placeholder="Search projects..."
 66→            className="w-full bg-transparent outline-none text-2xl"
 67→            style={{
 68→              color: 'var(--text-muted)',
 69→              fontFamily: 'var(--font-display)',
 70→              fontWeight: 400,
 71→              letterSpacing: '0.02em'
 72→            }}
 73→          />
 74→
 75→          {/* Close button */}
 76→          <button
 77→            onClick={onClose}
 78→            className="absolute right-0 top-1/2 -translate-y-1/2 hover:opacity-70 transition-opacity"
 79→            aria-label="Close search"
 80→          >
 81→            <svg
 82→              width="24"
 83→              height="24"
 84→              viewBox="0 0 24 24"
 85→              fill="none"
 86→              stroke="var(--text-muted)"
 87→              strokeWidth="2"
 88→              strokeLinecap="round"
 89→              strokeLinejoin="round"
 90→            >
 91→              <line x1="18" y1="6" x2="6" y2="18" />
 92→              <line x1="6" y1="6" x2="18" y2="18" />
 93→            </svg>
 94→          </button>
 95→        </div>
 96→
 97→        {/* Search hint */}
 98→        <p
 99→          className="mt-4 text-sm"
100→          style={{
101→            color: '#8a8a8a',
102→            fontFamily: 'var(--font-display)',
103→            fontWeight: 400
104→          }}
105→        >
106→          {searchQuery.length === 0 ? (
107→            'Type to search through projects, descriptions, and technologies'
108→          ) : (
109→            `Searching for "${searchQuery}"...`
110→          )}
111→        </p>
112→      </div>
113→
114→      <style jsx>{`
115→        @keyframes fadeIn {
116→          from {
117→            opacity: 0;
118→          }
119→          to {
120→            opacity: 1;
121→          }
122→        }
123→
124→        @keyframes slideDown {
125→          from {
126→            opacity: 0;
127→            transform: translateY(-20px);
128→          }
129→          to {
130→            opacity: 1;
131→            transform: translateY(0);
132→          }
133→        }
134→      `}</style>
135→    </div>
136→  );
137→}
