357→/* ===========================================
358→   FOCUS INDICATORS FOR ACCESSIBILITY
359→   =========================================== */
360→
361→/* Focus-visible indicators for keyboard navigation */
362→:focus-visible {
363→  outline: 2px solid rgba(255, 255, 255, 0.5);
364→  outline-offset: 2px;
365→}
366→
367→/* Remove focus ring on mouse click, keep for keyboard */
368→:focus:not(:focus-visible) {
369→  outline: none;
370→}
